mapper.select:
SELECT r.REPORT_ID, r.MODEL_ID, r.PERIOD, r.REPORT_TYPE, r.ITEM_CODE, r.ITEM_NAME, r.ITEM_LEVEL, r.PARENT_CODE, r.PARENT_AMOUNT, r.SUBSIDIARY_AMOUNT, r.ELIMINATION_AMOUNT, r.CONSOLIDATED_AMOUNT, r.SORT_ORDER, r.STATUS, r.TENANT_ID, r.CREATE_USER, r.CREATE_TIME, r.UPDATE_USER, r.UPDATE_TIME, m.MODEL_NAME FROM TBL_CONSOLIDATED_REPORT r LEFT JOIN TBL_CONSOLIDATION_MODEL m ON r.MODEL_ID = m.MODEL_ID
AND r.MODEL_ID = #{param.modelId}
AND r.PERIOD = #{param.period}
AND r.REPORT_TYPE = #{param.reportType}
AND r.STATUS = #{param.status}
ORDER BY r.REPORT_TYPE, r.SORT_ORDER, r.ITEM_CODE

mapper.delete:
DELETE FROM TBL_CONSOLIDATED_REPORT
WHERE MODEL_ID = #{modelId}
AND PERIOD = #{period}

    AND REPORT_TYPE = #{reportType}

mapper.select:
SELECT DISTINCT REPORT_TYPE
FROM TBL_CONSOLIDATED_REPORT
WHERE MODEL_ID = #{modelId}
AND PERIOD = #{period}
ORDER BY REPORT_TYPE
